    id: "gs-legacy-values-and-purpose",
    goal: "legacy", tier: "fundamental", section: "9209",
    title: "Name Your Values, Keep Your Purpose",
    subtitle: "Purpose in life predicts mortality; values affirmation changes behaviour",
    evidenceTag: "Strong",
